/* ============================================================
   AgendaBot :: Helpers comunes (sin dependencias externas)
   Zona horaria fija: America/Bogota (UTC-5, sin horario de verano)
   ============================================================ */
const TZ_OFFSET_MS = -5 * 60 * 60 * 1000;
function pad(n, l) { return String(n).padStart(l, '0'); }
function ahora() { return new Date(Date.now() + TZ_OFFSET_MS); }
function aFechaISO(d) { return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1, 2) + '-' + pad(d.getUTCDate(), 2); }
function aHoraHM(d) { return pad(d.getUTCHours(), 2) + ':' + pad(d.getUTCMinutes(), 2); }
function hoyISO() { return aFechaISO(ahora()); }
function horaActual() { return aHoraHM(ahora()); }
function timestampCO() { const d = ahora(); return aFechaISO(d) + ' ' + aHoraHM(d) + ':' + pad(d.getUTCSeconds(), 2); }
function sumarDias(f, n) {
  const p = String(f).split('-').map(Number);
  return aFechaISO(new Date(Date.UTC(p[0], p[1] - 1, p[2] + n)));
}
function esFechaValida(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const p = String(s).split('-').map(Number);
  if (p[1] < 1 || p[1] > 12) return false;
  const diasMes = new Date(Date.UTC(p[0], p[1], 0)).getUTCDate();
  return p[2] >= 1 && p[2] <= diasMes && p[0] >= 2000 && p[0] <= 2100;
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s || '')); }
function esPasado(f, h) {
  const hoy = hoyISO();
  if (f < hoy) return true;
  if (f === hoy && h && h <= horaActual()) return true;
  return false;
}
function vacio(s) { return String(s == null ? '' : s).trim().length === 0; }
function limpiar(s) { return String(s == null ? '' : s).trim().replace(/\s+/g, ' ').slice(0, 200); }
function filasReales(items, clave) {
  return items.map(function (i) { return i.json; })
              .filter(function (r) { return r && r[clave] != null && String(r[clave]).trim() !== ''; });
}
function siguienteId(filas, campo, prefijo) {
  let max = 0;
  for (const r of filas) {
    const m = String(r[campo] || '').match(/(\d+)\s*$/);
    if (m) { const n = parseInt(m[1], 10); if (n > max) max = n; }
  }
  return prefijo + '-' + pad(max + 1, 3);
}
function leerDatos(t) { try { const o = JSON.parse(t || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
function esVerdadero(v) {
  const s = String(v == null ? '' : v).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === 'SI' || s === 'SÍ' || s === '1' || s === 'X' || s === 'YES';
}
const PIE = '\n————————\n9 Volver   ·   /menu Menú principal   ·   /cancelar Cancelar';
function opcionInvalida(extra) {
  return '⚠️ No entendí esa opción.\n' + (extra || 'Escribe únicamente el número de una de las opciones mostradas.');
}
function salida(mensaje, pantalla, paso, datos, resultado, accion, fila) {
  return [{ json: {
    mensaje: String(mensaje).slice(0, 3900),
    pantalla_nueva: pantalla,
    paso_nuevo: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    resultado: resultado || 'OK',
    accion: accion || 'NINGUNA',
    fila: fila || {}
  }}];
}

/* =====================================================================
   MODULO TAREAS
   Pantallas: TAREAS | TAREAS_NUEVA (4 pasos) | TAREAS_ESTADO (2 pasos)
              TAREAS_CANCELAR (1 paso)
   Hoja: TAREAS(id_tarea, titulo, prioridad, estado, fecha_objetivo, creado_por)
   ===================================================================== */
const ctx = $('▶️ Entrada Tareas').first().json;
const filas = filasReales($input.all(), 'id_tarea');

const texto = String(ctx.texto || '').trim();
const pantalla = String(ctx.pantalla_actual || 'TAREAS').toUpperCase();
const paso = String(ctx.paso_actual || '0');
const usuario = String(ctx.telegram_user);
const d = leerDatos(ctx.datos_parciales);

const PRIORIDADES = { '1': 'ALTA', '2': 'MEDIA', '3': 'BAJA' };
const ESTADOS = { '1': 'PENDIENTE', '2': 'EN PROGRESO', '3': 'COMPLETADA' };
const ABIERTAS = ['PENDIENTE', 'EN PROGRESO'];
const ICONO = { 'PENDIENTE': '⬜', 'EN PROGRESO': '🔄', 'COMPLETADA': '✅', 'CANCELADA': '🚫' };
const PRIO_ICONO = { 'ALTA': '🔴', 'MEDIA': '🟡', 'BAJA': '🟢' };
const MANANA = sumarDias(hoyISO(), 1);

const MENU =
  '✅ TAREAS\n' +
  'Aquí organizas lo que tienes pendiente.\n\n' +
  '1  Crear tarea\n' +
  '2  Ver mis tareas\n' +
  '3  Cambiar estado de una tarea\n' +
  '4  Cancelar tarea\n' +
  '9  Volver al menú principal\n\n' +
  '💡 Recomendado: 2 Ver mis tareas\n' +
  'Tip: escribe únicamente el número.';

/* Entrada directa desde el menu principal: se muestra el menu del modulo
   sin consumir el numero que el usuario uso para entrar. */
if (ctx.entrada_modulo === true || String(ctx.entrada_modulo) === 'true')
  return salida(MENU, 'TAREAS', '0', {}, 'MENU_TAREAS');


function mias(estados) {
  return filas.filter(function (r) {
    return String(r.creado_por || '').trim() === usuario &&
           (!estados || estados.indexOf(String(r.estado || '').trim().toUpperCase()) !== -1);
  }).sort(function (a, b) {
    const pa = { 'ALTA': 0, 'MEDIA': 1, 'BAJA': 2 }[String(a.prioridad || '').toUpperCase()];
    const pb = { 'ALTA': 0, 'MEDIA': 1, 'BAJA': 2 }[String(b.prioridad || '').toUpperCase()];
    if (pa !== pb) return (pa == null ? 9 : pa) - (pb == null ? 9 : pb);
    return String(a.fecha_objetivo || '9999').localeCompare(String(b.fecha_objetivo || '9999'));
  });
}

function listado(ts) {
  return ts.map(function (t, i) {
    const e = String(t.estado || '').toUpperCase();
    const p = String(t.prioridad || '').toUpperCase();
    return (i + 1) + ')  ' + (ICONO[e] || '•') + ' ' + t.titulo +
           '\n      ' + (PRIO_ICONO[p] || '') + ' ' + p + '  ·  ' + e +
           '  ·  ' + (t.fecha_objetivo ? '📅 ' + t.fecha_objetivo : 'sin fecha') +
           '  ·  ' + t.id_tarea;
  }).join('\n');
}

function fila(t, cambios) {
  return {
    id_tarea: t.id_tarea,
    titulo: (cambios && cambios.titulo) || t.titulo,
    prioridad: (cambios && cambios.prioridad) || t.prioridad,
    estado: (cambios && cambios.estado) || t.estado,
    fecha_objetivo: (cambios && cambios.fecha_objetivo !== undefined) ? cambios.fecha_objetivo : t.fecha_objetivo,
    creado_por: t.creado_por
  };
}

const T1 = '🆕 NUEVA TAREA — Paso 1 de 4: TÍTULO\n\n' +
           '¿Qué necesitas hacer?\n' +
           'Escríbelo en una frase corta.\n\n' +
           'Ejemplo: Enviar la cotización al cliente\n\n' +
           '9 Volver   ·   /cancelar Cancelar';
const T2 = '🆕 NUEVA TAREA — Paso 2 de 4: PRIORIDAD\n\n' +
           '¿Qué tan urgente es?\n\n' +
           '1  🔴 Alta\n' +
           '2  🟡 Media\n' +
           '3  🟢 Baja\n\n' +
           '💡 Recomendado: 2 Media\n' +
           '9 Volver   ·   /cancelar Cancelar';
const T3 = '🆕 NUEVA TAREA — Paso 3 de 4: FECHA OBJETIVO\n\n' +
           '¿Para cuándo debe estar lista?\n' +
           'Formato AAAA-MM-DD. Ejemplo: ' + MANANA + '\n\n' +
           'Si no quieres ponerle fecha, escribe 0.\n\n' +
           '💡 Recomendado: ' + MANANA + '\n' +
           '9 Volver   ·   /cancelar Cancelar';

function resumen() {
  return '📋 RESUMEN DE LA TAREA\n\n' +
         '📝 Título:     ' + d.titulo + '\n' +
         '⚡ Prioridad:  ' + d.prioridad + '\n' +
         '📅 Fecha:      ' + (d.fecha_objetivo || 'sin fecha') + '\n\n' +
         '1  Confirmar y guardar\n' +
         '2  Editar desde el principio\n' +
         '3  Cancelar\n\n' +
         '💡 Recomendado: 1 Confirmar y guardar';
}

/* ------------------------------------------------------------------ MENU */
if (pantalla === 'TAREAS') {
  if (texto === '1') return salida(T1, 'TAREAS_NUEVA', '1', {}, 'WIZARD_INICIADO');
  if (texto === '2') {
    const ts = mias(null);
    if (ts.length === 0)
      return salida('📭 Todavía no tienes tareas registradas.\n\n' + MENU,
                    'TAREAS', '0', {}, 'CONSULTA_VACIA');
    const abiertas = ts.filter(function (t) { return ABIERTAS.indexOf(String(t.estado || '').toUpperCase()) !== -1; });
    return salida('📋 TUS TAREAS (' + ts.length + ' en total · ' + abiertas.length + ' abiertas)\n\n' +
                  listado(ts.slice(0, 20)) +
                  (ts.length > 20 ? '\n\n… y ' + (ts.length - 20) + ' más.' : '') +
                  '\n\n' + MENU, 'TAREAS', '0', {}, 'CONSULTA_OK');
  }
  if (texto === '3' || texto === '4') {
    const ts = mias(ABIERTAS);
    const destino = texto === '3' ? 'TAREAS_ESTADO' : 'TAREAS_CANCELAR';
    const verbo = texto === '3' ? 'cambiar de estado' : 'cancelar';
    if (ts.length === 0)
      return salida('📭 No tienes tareas abiertas que puedas ' + verbo + '.\n\n' + MENU,
                    'TAREAS', '0', {}, 'SIN_TAREAS');
    return salida('🔧 ¿Cuál tarea quieres ' + verbo + '?\n\n' + listado(ts) + '\n\n' +
                  'Escribe el número de la tarea (1 a ' + ts.length + ').\n\n' +
                  '💡 Recomendado: 1\n9 Volver   ·   /cancelar Cancelar',
                  destino, '1', { opciones: ts.map(function (t) { return t.id_tarea; }) },
                  'SELECCION_PEDIDA');
  }
  if (texto === '9') return salida('👌 Volvamos al menú principal.\n\nEscribe /menu para verlo.',
                                   'MENU', '0', {}, 'VOLVER');
  return salida(opcionInvalida('En Tareas espero un número del 1 al 4, o 9 para volver.') +
                '\n\n' + MENU, 'TAREAS', '0', {}, 'OPCION_INVALIDA');
}

/* ------------------------------------------------------- WIZARD DE ALTA */
if (pantalla === 'TAREAS_NUEVA') {
  if (paso === '1') {
    if (texto === '9') return salida(MENU, 'TAREAS', '0', {}, 'VOLVER');
    const t = limpiar(texto);
    if (vacio(t)) return salida('⚠️ El título no puede quedar vacío.\n\n' + T1,
                                'TAREAS_NUEVA', '1', d, 'VACIO');
    if (t.length < 3) return salida('⚠️ Ese título es muy corto. Usa al menos 3 caracteres.\n\n' + T1,
                                    'TAREAS_NUEVA', '1', d, 'TITULO_CORTO');
    d.titulo = t;
    return salida('✅ Título registrado: ' + d.titulo + '\n\n' + T2,
                  'TAREAS_NUEVA', '2', d, 'PASO_1_OK');
  }
  if (paso === '2') {
    if (texto === '9') return salida(T1, 'TAREAS_NUEVA', '1', d, 'VOLVER_PASO');
    const p = PRIORIDADES[texto];
    if (!p) return salida(opcionInvalida('Para la prioridad espero 1, 2 o 3.') + '\n\n' + T2,
                          'TAREAS_NUEVA', '2', d, 'PRIORIDAD_INVALIDA');
    d.prioridad = p;
    return salida('✅ Prioridad registrada: ' + d.prioridad + '\n\n' + T3,
                  'TAREAS_NUEVA', '3', d, 'PASO_2_OK');
  }
  if (paso === '3') {
    if (texto === '9') return salida(T2, 'TAREAS_NUEVA', '2', d, 'VOLVER_PASO');
    if (texto === '0') {
      d.fecha_objetivo = '';
    } else {
      if (!esFechaValida(texto))
        return salida('⚠️ Formato de fecha incorrecto. Debe ser AAAA-MM-DD, ' +
                      'por ejemplo ' + MANANA + '. Escribe 0 si no quieres fecha.\n\n' + T3,
                      'TAREAS_NUEVA', '3', d, 'FECHA_INVALIDA');
      if (texto < hoyISO())
        return salida('⚠️ Esa fecha ya pasó. Hoy es ' + hoyISO() + '.\n\n' + T3,
                      'TAREAS_NUEVA', '3', d, 'FECHA_PASADA');
      d.fecha_objetivo = texto;
    }
    return salida('✅ Fecha registrada.\n\n' + resumen(), 'TAREAS_NUEVA', '4', d, 'PASO_3_OK');
  }
  if (paso === '4') {
    if (texto === '2' || texto === '9')
      return salida('✏️ Empecemos de nuevo.\n\n' + T1, 'TAREAS_NUEVA', '1', {}, 'EDITAR');
    if (texto === '3')
      return salida('🗑️ Descarté la tarea. No guardé nada.\n\n' + MENU, 'TAREAS', '0', {}, 'CANCELADO');
    if (texto !== '1')
      return salida(opcionInvalida('Aquí espero 1, 2 o 3.') + '\n\n' + resumen(),
                    'TAREAS_NUEVA', '4', d, 'OPCION_INVALIDA');
    if (!d.titulo || !d.prioridad)
      return salida('⚠️ Faltan datos. Repetimos el proceso.\n\n' + T1,
                    'TAREAS_NUEVA', '1', {}, 'DATOS_INCOMPLETOS');

    const id = siguienteId(filas, 'id_tarea', 'TAREA');
    const f = {
      id_tarea: id, titulo: d.titulo, prioridad: d.prioridad, estado: 'PENDIENTE',
      fecha_objetivo: d.fecha_objetivo || '', creado_por: usuario
    };
    return salida('🎉 Tarea creada correctamente.\n\n' +
                  '🆔 ' + id + '\n📝 ' + f.titulo + '\n⚡ ' + f.prioridad + '\n' +
                  '📅 ' + (f.fecha_objetivo || 'sin fecha') + '\n🔖 PENDIENTE\n\n' + MENU,
                  'TAREAS', '0', {}, 'TAREA_CREADA:' + id, 'CREAR', f);
  }
  return salida(T1, 'TAREAS_NUEVA', '1', {}, 'PASO_DESCONOCIDO');
}

/* --------------------------------------------------- CAMBIO DE ESTADO */
if (pantalla === 'TAREAS_ESTADO' || pantalla === 'TAREAS_CANCELAR') {
  if (texto === '9') return salida(MENU, 'TAREAS', '0', {}, 'VOLVER');
  const ids = Array.isArray(d.opciones) ? d.opciones : [];

  if (paso === '1') {
    const n = parseInt(texto, 10);
    if (!/^\d+$/.test(texto) || isNaN(n) || n < 1 || n > ids.length)
      return salida(opcionInvalida('Escribe un número entre 1 y ' + ids.length + '.'),
                    pantalla, '1', d, 'SELECCION_INVALIDA');
    const t = filas.find(function (r) { return String(r.id_tarea) === String(ids[n - 1]); });
    if (!t) return salida('⚠️ No encontré esa tarea.\n\n' + MENU, 'TAREAS', '0', {}, 'NO_ENCONTRADA');

    if (pantalla === 'TAREAS_CANCELAR') {
      return salida('🚫 Tarea cancelada.\n\n🆔 ' + t.id_tarea + '\n📝 ' + t.titulo +
                    '\n🔖 Estado: CANCELADA\n\n' + MENU,
                    'TAREAS', '0', {}, 'TAREA_CANCELADA:' + t.id_tarea,
                    'ACTUALIZAR', fila(t, { estado: 'CANCELADA' }));
    }
    d.id_tarea = t.id_tarea;
    return salida('🔄 ¿A qué estado la movemos?\n\n' +
                  'Tarea: ' + t.titulo + '\nEstado actual: ' + t.estado + '\n\n' +
                  '1  ⬜ Pendiente\n2  🔄 En progreso\n3  ✅ Completada\n\n' +
                  '💡 Recomendado: 3 Completada\n9 Volver   ·   /cancelar Cancelar',
                  'TAREAS_ESTADO', '2', d, 'ESTADO_PEDIDO');
  }

  if (paso === '2') {
    const e = ESTADOS[texto];
    if (!e) return salida(opcionInvalida('Espero 1, 2 o 3.'), 'TAREAS_ESTADO', '2', d, 'ESTADO_INVALIDO');
    const t = filas.find(function (r) { return String(r.id_tarea) === String(d.id_tarea); });
    if (!t) return salida('⚠️ No encontré esa tarea.\n\n' + MENU, 'TAREAS', '0', {}, 'NO_ENCONTRADA');
    return salida('✅ Estado actualizado.\n\n🆔 ' + t.id_tarea + '\n📝 ' + t.titulo +
                  '\nAntes: ' + t.estado + '\nAhora: ' + e + '\n\n' + MENU,
                  'TAREAS', '0', {}, 'ESTADO_CAMBIADO:' + t.id_tarea + '->' + e,
                  'ACTUALIZAR', fila(t, { estado: e }));
  }
  return salida(MENU, 'TAREAS', '0', {}, 'PASO_DESCONOCIDO');
}

return salida(MENU, 'TAREAS', '0', {}, 'PANTALLA_DESCONOCIDA');

const r = $('🧠 Lógica de Tareas').first().json;
return [{ json: {
  mensaje: r.mensaje, pantalla_nueva: r.pantalla_nueva, paso_nuevo: r.paso_nuevo,
  datos_parciales: r.datos_parciales, resultado: r.resultado
}}];
